class ProjectManager {}
class Project {
  +startDate : date
  +endDate : date
}
abstract class WorkProduct {
  +description : string
  +percentComplete : float
  +validate()
}
class Requirement extends WorkProduct {}
class System extends WorkProduct {}
class User {
  +validate(workshops)
}
class Platform {}

ProjectManager "1" -- "1" Project : leads
Project "1" -- "1..*" Requirement : uses
Project "1" -- "0..1" System : produces
Requirement "1" -- "0..*" User : validated with
System "1" -- "1" Requirement : tested against
Requirement "1" -- "*" Requirement : published on
System "1" -- "1" Platform : deployed onto
@enduml

